    OPT_WARN_FOOD = { "Buff food (Well Fed)", "Buff-Essen (Satt)", "Nourriture (Bien nourri)", "Comida (Bien alimentado)", "Еда (Сытость)", "增益食物（进食充分）" },
    OPT_WARN_FOOD_TIP = { "Warns when you are not Well Fed.", "Warnt, wenn du nicht satt bist.", "Alerte si vous n'êtes pas bien nourri.", "Avisa si no estás bien alimentado.", "Предупреждает, если нет сытости.", "未进食充分时提醒。" },
    OPT_WARN_WEAPON = { "Weapon buffs missing", "Waffenbuffs fehlen", "Améliorations d'arme manquantes", "Faltan mejoras de arma", "Нет усилений оружия", "缺少武器增益" },
    OPT_WARN_WEAPON_TIP = { "Rogues and shamans always; everyone else after a stone or oil ran out.", "Schurken und Schamanen immer; alle anderen, nachdem ein Stein oder Öl abgelaufen ist.", "Voleurs et chamans toujours ; les autres après expiration d'une pierre ou huile.", "Pícaros y chamanes siempre; el resto cuando se acaba una piedra o aceite.", "Разбойники и шаманы всегда; остальные после окончания камня или масла.", "潜行者和萨满始终提醒；其他职业在磨刀石或油失效后提醒。" },
    OPT_WARN_EXPIRING = { "Own buffs about to run out", "Eigene Buffs laufen bald ab", "Améliorations sur le point d'expirer", "Beneficios a punto de acabar", "Баффы скоро закончатся", "自身增益即将结束" },
