    OPT_TOOLTIP_TIP = { "Sell value, count per character, gathering skill.", "Verkaufswert, Anzahl pro Charakter, Sammel-Skill.", "Valeur de vente, quantité par personnage, compétence de récolte.", "Valor de venta, cantidad por personaje, habilidad de recolección.", "Цена продажи, количество у персонажей, навык сбора.", "售价、各角色数量、采集技能。" },
    OPT_TT_SELL = { "Sell value", "Verkaufswert", "Valeur de vente", "Valor de venta", "Цена продажи", "售价" },
