    OPT_TT_COUNTS_TIP = { "Bags and bank of your characters on this realm and faction. The bank is read whenever you open it.", "Taschen und Bank deiner Charaktere auf diesem Realm und dieser Fraktion. Die Bank wird beim Öffnen gelesen.", "Sacs et banque de vos personnages de ce royaume et de cette faction. La banque est lue à son ouverture.", "Bolsas y banco de tus personajes de este reino y facción. El banco se lee al abrirlo.", "Сумки и банк ваших персонажей этого мира и фракции. Банк читается при открытии.", "本服务器和阵营角色的背包与银行。银行在打开时读取。" },
    OPT_TT_GATHER = { "Gathering skill", "Sammel-Skill", "Compétence de récolte", "Habilidad de recolección", "Навык сбора", "采集技能" },
    OPT_TT_GATHER_TIP = { "The skill herbs, mineral veins and skinnable creatures need, coloured by your own skill.", "Der Skill, den Kräuter, Erzvorkommen und kürschnerbare Kreaturen brauchen, gefärbt nach deinem Skill.", "La compétence requise pour herbes, filons et créatures à dépecer, colorée selon la vôtre.", "La habilidad que necesitan hierbas, vetas y criaturas desollables, coloreada según la tuya.", "Навык для трав, жил и свежевания, окрашенный по вашему уровню.", "草药、矿脉和可剥皮生物所需技能，按你的技能着色。" },
