    TT_SKILL = { "Requires %s (%d)", "Benötigt %s (%d)", "Nécessite %s (%d)", "Requiere %s (%d)", "Требуется: %s (%d)", "需要%s（%d）" },
    WZ_PANEL = { "The panel", "Das Panel", "Le panneau", "El panel", "Панель", "面板" },
    WZ_PANEL_TEXT = { "An info bar at the edge of the screen: gold, bags, durability, zone, clock and more. Drag its elements to arrange them, right-click it to choose which ones are shown. It folds away when you do not need it.", "Eine Infoleiste am Bildschirmrand: Gold, Taschen, Haltbarkeit, Zone, Uhr und mehr. Ihre Elemente lassen sich per Ziehen umsortieren, ein Rechtsklick wählt aus, welche zu sehen sind. Sie klappt ein, wenn du sie nicht brauchst.", "Une barre d'infos au bord de l'écran : or, sacs, durabilité, zone, horloge et plus. Glissez ses éléments pour les ranger, clic droit pour choisir lesquels afficher. Elle se replie quand vous n'en avez pas besoin.", "Una barra de información en el borde de la pantalla: oro, bolsas, durabilidad, zona, reloj y más. Arrastra sus elementos para ordenarlos y haz clic derecho para elegir cuáles se ven. Se pliega cuando no la necesitas.", "Информационная панель у края экрана: золото, сумки, прочность, зона, часы и многое другое. Элементы можно перетаскивать, ПКМ выбирает, какие показывать. Сворачивается, когда не нужна.", "屏幕边缘的信息栏：金币、背包、耐久、区域、时钟等。拖动元素可调整顺序，右键点击可选择显示哪些元素。不需要时会自动收起。" },
    WZ_XPBAR = { "The XP bar", "Die EP-Leiste", "La barre d'XP", "La barra de PE", "Полоса опыта", "经验条" },
    WZ_XPBAR_TEXT = { "Built into the panel, with rested XP and a preview of the XP your finished quests will give.", "Ins Panel eingebaut, mit Ruhebonus und einer Vorschau der EP, die deine fertigen Quests bringen.", "Intégrée au panneau, avec le repos et un aperçu de l'XP des quêtes terminées.", "Integrada en el panel, con descanso y una vista previa de la PE de las misiones completadas.", "Встроена в панель, с отдыхом и предпросмотром опыта за выполненные задания.", "嵌入面板，显示休息经验以及已完成任务将获得的经验预览。" },
    WZ_MINIMAP = { "Minimap buttons", "Minimap-Buttons", "Boutons de la minicarte", "Botones del minimapa", "Кнопки миникарты", "小地图按钮" },
    WZ_MINIMAP_TEXT = { "The buttons other addons put around the minimap move into one tidy menu.", "Die Buttons, die andere Addons um die Minimap legen, wandern in ein aufgeräumtes Menü.", "Les boutons des autres addons autour de la minicarte rejoignent un menu ordonné.", "Los botones que otros addons ponen alrededor del minimapa pasan a un menú ordenado.", "Кнопки других аддонов вокруг миникарты собираются в аккуратное меню.", "其他插件放在小地图周围的按钮会收进一个整洁的菜单。" },
    WZ_AB_TEXT = { "New spells and new ranks go onto your action bars by themselves.", "Neue Zauber und neue Ränge landen von selbst auf deinen Aktionsleisten.", "Les nouveaux sorts et rangs vont d'eux-mêmes sur vos barres d'action.", "Los hechizos y rangos nuevos van solos a tus barras de acción.", "Новые заклинания и ранги сами попадают на панели команд.", "新法术和新等级会自动放到你的动作条上。" },
    WZ_QUESTS_TEXT = { "Quests are accepted and turned in for you. Hold Shift to pause it at any time.", "Quests werden für dich angenommen und abgegeben. Shift halten pausiert das jederzeit.", "Les quêtes sont acceptées et rendues pour vous. Maintenez Maj pour mettre en pause.", "Las misiones se aceptan y entregan por ti. Mantén Mayús para pausar.", "Задания принимаются и сдаются за вас. Удерживайте Shift для паузы.", "自动接受和交付任务。随时按住Shift暂停。" },
    WZ_MERCHANT_TEXT = { "Grey items are sold and your gear repaired as soon as you talk to a merchant.", "Graue Gegenstände werden verkauft und deine Ausrüstung repariert, sobald du mit einem Händler sprichst.", "Les objets gris sont vendus et votre équipement réparé dès que vous parlez à un marchand.", "Los objetos grises se venden y tu equipo se repara al hablar con un mercader.", "Серые предметы продаются, а снаряжение чинится при разговоре с торговцем.", "与商人交谈时自动出售灰色物品并修理装备。" },
    WZ_NP_TEXT = { "Creatures your quests still need show a quest icon on their nameplate.", "Kreaturen, die deine Quests noch brauchen, zeigen ein Quest-Symbol an ihrer Namensplakette.", "Les créatures dont vos quêtes ont besoin affichent une icône sur leur barre de nom.", "Las criaturas que tus misiones necesitan muestran un icono en su placa.", "Существа, нужные для заданий, отмечены значком на индикаторе.", "任务仍需要的生物会在姓名板上显示任务图标。" },
    WZ_WARN_TEXT = { "A quiet note when a buff is missing or about to run out.", "Ein dezenter Hinweis, wenn ein Buff fehlt oder bald abläuft.", "Une note discrète quand une amélioration manque ou va expirer.", "Un aviso discreto cuando falta un beneficio o va a acabar.", "Ненавязчивое напоминание, если баффа нет или он заканчивается.", "增益缺失或即将结束时给出低调提示。" },
    WZ_TT_TEXT = { "More in your tooltips: sell value, how many each character has, and the skill a herb or vein needs.", "Mehr in deinen Tooltips: Verkaufswert, wie viele jeder Charakter hat und welchen Skill ein Kraut oder Erz braucht.", "Plus dans vos infobulles : valeur de vente, quantité par personnage et compétence requise.", "Más en tus descripciones: valor de venta, cuántos tiene cada personaje y la habilidad necesaria.", "Больше в подсказках: цена продажи, количество у персонажей и нужный навык сбора.", "鼠标提示中的更多信息：售价、各角色数量、采集所需技能。" },
    WZ_WELCOME = { "Welcome! A few questions and everything is set up the way you like it. You can change all of it later in the options.", "Willkommen! Ein paar Fragen, dann ist alles so eingerichtet, wie du es magst. Alles lässt sich später in den Optionen ändern.", "Bienvenue ! Quelques questions et tout sera réglé à votre goût. Tout reste modifiable dans les options.", "¡Bienvenido! Unas preguntas y todo quedará a tu gusto. Todo se puede cambiar luego en las opciones.", "Добро пожаловать! Несколько вопросов — и всё настроено. Всё можно изменить в настройках.", "欢迎！回答几个问题即可按你的喜好完成设置，之后都可以在选项中修改。" },
    WZ_UPDATE = { "New in version %s:", "Neu in Version %s:", "Nouveau dans la version %s :", "Novedades de la versión %s:", "Новое в версии %s:", "%s 版本新增：" },
    WZ_NEW = { "NEW", "NEU", "NOUVEAU", "NUEVO", "НОВОЕ", "新" },
