    WZ_OPEN_TIP = { "All pages of the setup wizard again. Also: /fqp setup", "Alle Seiten des Assistenten noch einmal. Auch: /fqp setup", "Toutes les pages de l'assistant. Aussi : /fqp setup", "Todas las páginas del asistente. También: /fqp setup", "Все страницы мастера заново. Также: /fqp setup", "再次打开向导全部页面。也可用：/fqp setup" },
    WZ_STEP = { "Step %d of %d", "Schritt %d von %d", "Étape %d sur %d", "Paso %d de %d", "Шаг %d из %d", "第 %d 步，共 %d 步" },
