    OPT_WINDOW_TEXT = { "The settings of Forever QoL Panel have their own window.", "Die Einstellungen von Forever QoL Panel haben ein eigenes Fenster.", "Les réglages de Forever QoL Panel ont leur propre fenêtre.", "Los ajustes de Forever QoL Panel tienen su propia ventana.", "Настройки Forever QoL Panel открываются в отдельном окне.", "Forever QoL Panel 的设置在单独的窗口中。" },
    OPT_OPEN_BTN = { "Open settings", "Einstellungen öffnen", "Ouvrir les réglages", "Abrir ajustes", "Открыть настройки", "打开设置" },
    OPT_WARN_COMBAT = { "Also in combat", "Auch im Kampf", "Aussi en combat", "También en combate", "Также в бою", "战斗中也显示" },
    OPT_WARN_COMBAT_TIP = { "Keep the warnings visible during combat. The game locks buff data in combat, so they show the state from before the fight.", "Warnungen auch im Kampf sichtbar lassen. Das Spiel sperrt Buff-Daten im Kampf, daher zeigen sie den Stand von vor dem Kampf.", "Garder les alertes visibles en combat. Le jeu verrouille les données d'améliorations en combat : elles montrent l'état d'avant le combat.", "Mantener los avisos visibles en combate. El juego bloquea los datos de beneficios en combate, así que muestran el estado previo al combate.", "Оставлять предупреждения в бою. В бою игра блокирует данные об эффектах, поэтому показывается состояние до боя.", "战斗中保留警告显示。战斗中游戏会锁定增益数据，因此显示战斗前的状态。" },
    OPT_WARN_SCALE = { "Size", "Größe", "Taille", "Tamaño", "Размер", "大小" },
    OPT_WARN_MOVE = { "Position", "Position", "Position", "Posición", "Положение", "位置" },
    OPT_WARN_MOVE_BTN = { "Move", "Verschieben", "Déplacer", "Mover", "Переместить", "移动" },
    OPT_WARN_MOVE_TIP = { "Shows example warnings in a blue box: drag them where you want them. Right-click the box or press the button again to finish.", "Zeigt Beispiel-Warnungen in einem blauen Kasten: an die gewünschte Stelle ziehen. Rechtsklick auf den Kasten oder erneut den Knopf drücken zum Beenden.", "Affiche des alertes d'exemple dans un cadre bleu : faites-les glisser où vous voulez. Clic droit sur le cadre ou rappuyez sur le bouton pour terminer.", "Muestra avisos de ejemplo en un recuadro azul: arrástralos adonde quieras. Clic derecho en el recuadro o pulsa de nuevo el botón para terminar.", "Показывает примеры предупреждений в синей рамке: перетащите их куда нужно. ПКМ по рамке или повторное нажатие кнопки — готово.", "在蓝色框中显示示例警告：拖动到想要的位置。右键点击框或再次按下按钮即可完成。" },
    OPT_WARN_RESET = { "Default position", "Standardposition", "Position par défaut", "Posición predeterminada", "Положение по умолчанию", "默认位置" },
    OPT_WARN_RESET_BTN = { "Reset", "Zurücksetzen", "Réinitialiser", "Restablecer", "Сбросить", "重置" },
    WARN_MOVE_HINT = { "Drag to move. Drop next to the other box to group them, Shift-drag to split. Right-click: done", "Ziehen zum Verschieben. An den anderen Kasten ziehen gruppiert, Shift-Ziehen trennt. Rechtsklick: fertig", "Glisser pour déplacer. Déposer à côté de l'autre cadre pour grouper, Maj-glisser pour séparer. Clic droit : terminé", "Arrastra para mover. Suelta junto al otro recuadro para agrupar, Mayús-arrastrar para separar. Clic derecho: listo", "Перетащите. Рядом с другой рамкой — группа, Shift-перетаскивание — разделить. ПКМ — готово", "拖动以移动。拖到另一个框旁边可编组，Shift-拖动可拆分。右键：完成" },
    OPT_WARN_SHAPE = { "Icon shape", "Icon-Form", "Forme de l'icône", "Forma del icono", "Форма значка", "图标形状" },
    SHAPE_PANEL = { "Like the panel", "Wie im Panel", "Comme le panneau", "Como el panel", "Как на панели", "与面板相同" },
    OPT_WARN_ANIM = { "Animation", "Animation", "Animation", "Animación", "Анимация", "动画" },
    OPT_WARN_ANIM_TIP = { "How a new warning draws attention. It plays a few times and then stays still.", "Wie eine neue Warnung auf sich aufmerksam macht. Sie läuft ein paar Mal und bleibt dann ruhig.", "Comment une nouvelle alerte attire l'attention. Elle se joue quelques fois puis reste immobile.", "Cómo llama la atención un aviso nuevo. Se reproduce unas veces y luego queda quieto.", "Как новое предупреждение привлекает внимание. Проигрывается несколько раз, затем замирает.", "新警告如何引起注意。播放几次后保持静止。" },
